/**
 * Single source of truth for how docs, hooks, and warnings invoke gitnexus.
 *
 * Automatically selects a working invocation path:
 * 1. Global `gitnexus` on PATH (best ΓÇö no install step)
 * 2. npm 11+ with pnpm on PATH ΓåÆ `pnpm --allow-build=ΓÇª dlx` (avoids the npx
 *    arborist crash *and* pnpm 10+ ignored-build-script failures, #1939)
 * 3. npm 11+ without pnpm but with bunx ΓåÆ `bunx` (dodges the same crash)
 * 4. npm < 11 with npm on PATH ΓåÆ `npx` (works; simpler than pnpm dlx)
 * 5. pnpm-only ΓåÆ `pnpm --allow-build=ΓÇª dlx`
 * 6. bun-only ΓåÆ `bunx`
 * 7. Last resort ΓåÆ `npx` (warned on npm 11+ from analyze.ts)
 *
 * The bun branches exist because a Node toolchain is no longer implied: on a
 * bun-only machine npm, npx and pnpm are all absent, so every rung above
 * resolved to `npx` and the emitted command could not run at all. `bunx` is
 * bun's install-free one-shot runner and needs no allow-build equivalent ΓÇö bun
 * skips lifecycle scripts unconditionally for a `bunx` fetch, which the native
 * loader recovers from directly (see core/lbug/native-check.ts). Both bun rungs
 * gate on `bunx` actually running, not merely existing on PATH ΓÇö see `hasBun`.
 *
 * The `--allow-build` flags MUST precede the `dlx` token. pnpm < 10.14 keeps
 * `dlx` in its argv escape list, so flags placed *after* `dlx` are parsed as
 * package specs (ERR_PNPM_SPEC_NOT_SUPPORTED). The pre-`dlx` position parses
 * into dlx's allow-build option and has been honored since pnpm 10.2.0 (#1939).
 *
 * This stays self-contained CJS because the Claude/Antigravity hooks run as
 * standalone files copied into the user's hook dir, where no package import is
 * available. The CLI reuses this module from src/cli/resolve-invocation.ts via
 * createRequire rather than re-implementing it. Two committed copies must stay
 * byte-identical (enforced by resolve-invocation.test.ts) ΓÇö edit both together:
 * gitnexus/hooks/claude/ (the canonical copy the CLI and `gitnexus setup` read)
 * and gitnexus-claude-plugin/hooks/. A THIRD copy is written at runtime to
 * `<repo>/.gitnexus/run.cjs` by `gitnexus analyze` (ai-context.ts) so docs can
 * reference it directly via the `require.main === module` exec tail below; that
 * copy is gitignored and refreshed on every analyze, so it cannot drift for long.
 */

const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const NPX_REF = 'gitnexus@latest';

// Native packages whose postinstall must run under pnpm 10+ (blocked by default).
const PNPM_ALLOW_BUILD_BASE = ['@ladybugdb/core', 'gitnexus', 'tree-sitter'];
const PNPM_ALLOW_BUILD_EMBEDDINGS = ['onnxruntime-node'];

// Version-probe timeout, kept under Claude Code's 10s hook budget. PATH presence
// detection is now spawn-free (resolveOnPath scans PATH directly), so the only
// subprocesses left are the version probes: in a linked worktree the stale-index
// hook first runs `git rev-parse --git-common-dir` (~2s) and `git rev-parse HEAD`
// (~3s); the pnpm path then adds up to two 1s `--version` probes (npm, pnpm), so
// the worst case is ~7s ΓÇö within budget. A healthy `--version` returns in well
// under a second, so the realistic cost is far lower. The bun rungs add at most
// one more 1s probe (`bunx --version`), reached only when pnpm is unusable and
// npm is 11+ or unreadable, for a ~8s theoretical cap. That cap needs an absent
// pnpm to burn its full second, which only Windows can do (`shell: true` spawns
// cmd.exe); on POSIX an absent pnpm ENOENTs in ~1ms, so the real ceiling is
// unmoved.
const PROBE_TIMEOUT_MS = 1000;

/**
 * Absolute path to `command` on PATH, or null ΓÇö a pure-Node, spawn-free lookup
 * that mirrors how a shell resolves a bare command name: each PATH dir ├ù the
 * platform's executable extensions (PATHEXT on Windows; the bare name + X_OK on
 * POSIX). This replaces the former `where`/`which` subprocess (#1938 "Option A"):
 * it is byte-for-byte identical on every OS, with no dependency on the probe
 * binary being reachable (a sanitized PATH that drops System32 / `/usr/bin` no
 * longer defeats detection), no shell-spawn surface (CVE-2024-27980), and no
 * spawn timeout to tune. On Windows it matches PATHEXT extensions ONLY ΓÇö exactly
 * what `where`/cmd.exe resolve ΓÇö so neither an un-spawnable `.ps1`-only shim (not
 * in default PATHEXT) nor a bare extensionless file (which the shell cannot launch
 * as `command`) is a false positive. `preferExecExt` returns a recognized
 * `.cmd`/`.bat`/`.exe` shim ahead of an exotic PATHEXT hit (e.g. `.COM`) when both
 * match, matching what a user would actually launch. Pure (platform/env injectable)
 * so it is unit-testable without touching the host PATH.
 */
function resolveOnPath(
  command,
  preferExecExt = false,
  { platform = process.platform, env = process.env } = {},
) {
  const pathValue = env.PATH || env.Path || env.path || '';
  if (!pathValue) return null;
  const isWin = platform === 'win32';
  const exts = isWin
    ? (env.PATHEXT || '.COM;.EXE;.BAT;.CMD')
        .split(';')
        .map((e) => e.trim())
        .filter(Boolean)
        .map((e) => (e.startsWith('.') ? e : `.${e}`))
    : [''];
  let weakHit = null;
  // Split on the host's PATH delimiter. `platform` is injected only to choose the
  // extension/exec-bit rules; the PATH string is always host-format, so it must
  // split on the host delimiter (`path.delimiter`) ΓÇö in production `platform` IS
  // the host, so they coincide. (Deriving the delimiter from an injected platform
  // would split a Windows drive-letter path `C:\ΓÇª` at its colon under a POSIX
  // injection.)
  for (const dir of pathValue.split(path.delimiter).filter(Boolean)) {
    for (const ext of exts) {
      const candidate = path.join(dir, `${command}${ext}`);
      try {
        if (!fs.statSync(candidate).isFile()) continue;
        if (!isWin) fs.accessSync(candidate, fs.constants.X_OK);
        // Prefer a runnable .cmd/.bat/.exe shim; remember an exotic PATHEXT hit
        // (e.g. .COM) only as a last resort if nothing better turns up.
        if (isWin && preferExecExt && !/\.(cmd|bat|exe)$/i.test(ext)) {
          weakHit = weakHit || candidate;
          continue;
        }
        return candidate;
      } catch {
        /* not a runnable file here ΓÇö try the next candidate */
      }
    }
  }
  return weakHit;
}

// One spawn of `<command> --version` ΓåÆ { ran, major, minor } (versions null when
// unreadable). Version injection happens at the resolver seam (getNpmMajorVersion
// / formatPnpmAllowBuildArgs), so this stays a pure real-process probe.
//
// `ran` is liveness, kept separate from the version because a PATH hit proves a
// file exists, not that it works, and the two answers differ: a banner-printing
// or oddly-versioned tool is alive with `major: null`, while a stale shim left by
// a partial uninstall is neither. Only the bun rung consults `ran` today (see
// hasBun) ΓÇö it is the one runner with no version to read, so a dedicated probe is
// its only liveness signal; pnpm gets the same evidence for free from the version
// spawn it must make anyway, and deliberately forgives an unreadable one (#1939).
function probeVersion(command) {
  try {
    const output = execFileSync(command, ['--version'], {
      encoding: 'utf-8',
      timeout: PROBE_TIMEOUT_MS,
      stdio: ['ignore', 'pipe', 'ignore'],
      windowsHide: true,
      // On Windows, npm/pnpm resolve to `.cmd` shims; execFileSync does no
      // PATHEXT resolution and Node refuses to spawn `.cmd`/`.bat` without a
      // shell (CVE-2024-27980), so a bare `<command> --version` ENOENTs and the
      // probe would wrongly report a present tool as absent. A shell lets the OS
      // resolve the shim. POSIX needs no shell (direct PATH lookup works).
      shell: process.platform === 'win32',
    });
    // Find the first line that starts with a version token (`MAJOR.MINOR`,
    // optional `v` prefix) rather than splitting the whole output ΓÇö pnpm/npm
    // under Corepack or with an update notice can print a banner line on stdout
    // before the version (stderr is already dropped via the stdio config).
    const versionLine = output
      .split('\n')
      .map((l) => l.trim())
      .find((l) => /^v?\d+\.\d+/.test(l));
    const match = versionLine ? versionLine.match(/^v?(\d+)\.(\d+)/) : null;
    return {
      ran: true,
      major: match ? Number(match[1]) : null,
      minor: match ? Number(match[2]) : null,
    };
  } catch {
    // Spawn failure, non-zero exit, or the timeout ΓÇö the command did not run.
    return { ran: false, major: null, minor: null };
  }
}

// `deps` is the single injection seam: an explicitly provided key ΓÇö including a
// `null` value, detected via `in` ΓÇö is honored as-is so tests can simulate an
// absent tool without spawning; an absent key falls through to the real probe.
function getNpmMajorVersion(deps = {}) {
  return 'npmMajor' in deps ? deps.npmMajor : probeVersion('npm').major;
}

/**
 * `--allow-build` flags for the pre-`dlx` position. Emitted for pnpm >= 10.2
 * (where the flag exists, and pnpm 10+ blocks build scripts by default). Omitted
 * below 10.2: pnpm < 10 runs build scripts anyway, and pnpm 10.0/10.1 lack the
 * flag (it would be rejected as an unknown option). `alwaysAllowBuild` forces the
 * flags for committed documentation, which cannot probe the reader's pnpm.
 */
function formatPnpmAllowBuildArgs(options = {}, deps = {}) {
  if (!options.alwaysAllowBuild) {
    const { major, minor } =
      'pnpmMajor' in deps
        ? { major: deps.pnpmMajor, minor: 'pnpmMinor' in deps ? deps.pnpmMinor : null }
        : probeVersion('pnpm');
    const lacksAllowBuild =
      major !== null && (major < 10 || (major === 10 && minor !== null && minor < 2));
    if (lacksAllowBuild) return [];
  }
  const pkgs = [...PNPM_ALLOW_BUILD_BASE];
  if (options.embeddings) pkgs.push(...PNPM_ALLOW_BUILD_EMBEDDINGS);
  return pkgs.map((p) => `--allow-build=${p}`);
}

/** Fixed install-free command for committed AGENTS.md / SKILL.md (pnpm >= 10.2). */
function formatDocumentationDlxCommand(gitnexusArgs, options = {}) {
  const flags = formatPnpmAllowBuildArgs({ ...options, alwaysAllowBuild: true }).join(' ');
  const prefix = flags ? `${flags} ` : '';
  return `pnpm ${prefix}dlx ${NPX_REF} ${gitnexusArgs}`;
}

/**
 * Resolve `gitnexus` | `pnpm` | `bun` | `npx`. `GITNEXUS_INVOCATION` forces a
 * mode (test/escape hatch). `probe` is injectable so the preference order can be
 * unit-tested without spawning; it defaults to the real PATH probe. `deps` can
 * inject `{ npmMajor, pnpmMajor, bunPresent, bunRuns }` for tests.
 */
function resolveInvocationMode(probe = resolveOnPath, deps = {}) {
  const forced = process.env.GITNEXUS_INVOCATION?.trim().toLowerCase();
  if (forced === 'gitnexus' || forced === 'pnpm' || forced === 'npx' || forced === 'bun') {
    return forced;
  }
  if (probe('gitnexus', true)) return 'gitnexus';

  const npmMajor = getNpmMajorVersion(deps);
  // pnpm presence: prefer an explicit `pnpmPresent` flag (set by
  // formatAnalyzeCommand, which falls back to a PATH probe when the version is
  // unreadable) so a present-but-unparseable pnpm ΓÇö slow probe, Corepack
  // banner ΓÇö still selects pnpm instead of the npx crash path. Otherwise an
  // injected version (a successful `pnpm --version` proves presence)
  // short-circuits the `which pnpm` probe; failing both, fall back to PATH.
  const hasPnpm =
    'pnpmPresent' in deps
      ? deps.pnpmPresent
      : 'pnpmMajor' in deps
        ? deps.pnpmMajor !== null
        : Boolean(probe('pnpm'));

  // bun usability is resolved lazily: only the two branches below can select it,
  // so a machine with pnpm, or with npm < 11, never pays the PATH scan or the
  // spawn. `bunx` (not `bun`) is probed because `bunx` is what the resolved
  // command actually runs. Two gates, `&&`-ordered cheapest first: a spawn-free
  // PATH scan, then liveness ΓÇö a PATH hit alone would route a present-but-broken
  // shim to a command that can only fail at execution time.
  let bunCache;
  const hasBun = () => {
    if (bunCache === undefined) {
      const present = 'bunPresent' in deps ? Boolean(deps.bunPresent) : Boolean(probe('bunx'));
      bunCache = present && ('bunRuns' in deps ? Boolean(deps.bunRuns) : probeVersion('bunx').ran);
    }
    return bunCache;
  };

  // npm 11+ npx install crash (#1939) ΓÇö prefer pnpm dlx when available.
  if (hasPnpm && npmMajor !== null && npmMajor >= 11) return 'pnpm';
  // Same crash, no pnpm to fall back on: bunx is install-free and unaffected.
  if (npmMajor !== null && npmMajor >= 11 && hasBun()) return 'bun';
  // npm 10 and earlier: npx works; prefer it over pnpm dlx when npm is present.
  if (npmMajor !== null && npmMajor < 11) return 'npx';
  // npm absent or unreadable ΓÇö use pnpm if present (with allow-build flags).
  if (hasPnpm) return 'pnpm';
  // Neither npm nor pnpm ΓÇö bunx is the only install-free runner left. Without
  // this rung a bun-only machine fell through to `npx`, which is not installed
  // there, so the emitted command failed with "npx: command not found".
  if (hasBun()) return 'bun';

  return 'npx';
}

function formatPnpmDlxCommand(gitnexusArgs, options = {}, deps = {}) {
  const flags = formatPnpmAllowBuildArgs(options, deps).join(' ');
  const prefix = flags ? `${flags} ` : '';
  return `pnpm ${prefix}dlx ${NPX_REF} ${gitnexusArgs}`;
}

/**
 * bun's install-free one-shot runner. Deliberately flag-free: bun has no
 * per-invocation `--allow-build` equivalent (`--trust` is a `bun add`/`bun
 * install` flag that writes trustedDependencies into a project package.json,
 * which a one-shot `bunx` has nowhere to put), so the skipped lifecycle copy is
 * recovered by the native loader instead of by the invocation.
 */
function formatBunxCommand(gitnexusArgs) {
  return `bunx ${NPX_REF} ${gitnexusArgs}`;
}

function formatAnalyzeCommand(options = {}, deps = {}) {
  // `--index-only` is what a routine "your index is stale" nudge wants: it
  // reindexes without rewriting AGENTS.md / CLAUDE.md / skills, so an agent
  // following the nudge on every commit cannot churn the tracked agent guides
  // (#2907). Callers that actually want the docs refreshed omit it.
  const suffix = `${options.indexOnly ? ' --index-only' : ''}${
    options.embeddings ? ' --embeddings' : ''
  }`;
  // Keep the stale-index hook budget tight by querying each tool at most once.
  // The memoized `probe` is a spawn-free PATH scan (resolveOnPath) shared with
  // resolveInvocationMode, so `gitnexus` is scanned only once and no subprocess
  // is spawned for presence. pnpm's *version* is still captured by a single
  // `pnpm --version` (the allow-build gate needs the number), which also proves
  // presence; the memoized scan only re-checks pnpm when that version is
  // unreadable. Injected deps (tests) and forced/global modes skip the pnpm probe.
  const cache = new Map();
  const probe = (command, gitnexusWrapper) => {
    const key = `${command}:${gitnexusWrapper ? 1 : 0}`;
    if (!cache.has(key)) cache.set(key, resolveOnPath(command, gitnexusWrapper));
    return cache.get(key);
  };
  let resolved = deps;
  if (!('pnpmMajor' in deps)) {
    const forced = process.env.GITNEXUS_INVOCATION?.trim().toLowerCase();
    // pnpm is only consulted when no non-pnpm mode is already certain: forced
    // gitnexus/npx never use pnpm, and a present global gitnexus wins outright.
    const mightUsePnpm =
      forced === 'pnpm' || (forced !== 'gitnexus' && forced !== 'npx' && forced !== 'bun');
    if (mightUsePnpm && (forced === 'pnpm' || !probe('gitnexus', true))) {
      const { major, minor } = probeVersion('pnpm');
      // Carry presence separately from version: when the version probe fails
      // (timeout, Corepack banner) but pnpm is on PATH, still treat it as
      // present so mode resolution picks pnpm over the npx crash path. The
      // PATH probe is memoized and only runs when the version is unreadable.
      const pnpmPresent = major !== null || Boolean(probe('pnpm'));
      resolved = { ...deps, pnpmMajor: major, pnpmMinor: minor, pnpmPresent };
    }
  }
  const mode = resolveInvocationMode(probe, resolved);
  if (mode === 'gitnexus') return `gitnexus analyze${suffix}`;
  if (mode === 'pnpm') return `${formatPnpmDlxCommand(`analyze${suffix}`, options, resolved)}`;
  if (mode === 'bun') return formatBunxCommand(`analyze${suffix}`);
  return `npx ${NPX_REF} analyze${suffix}`;
}

/**
 * Resolve `mode` into a concrete { program, args } pair for a set of gitnexus
 * subcommand arguments. Shared by the direct-exec entrypoint below; pure (no
 * spawn) so it is unit-testable. `--embeddings` widens the pnpm allow-build set.
 */
function buildRunnerArgv(mode, gitnexusArgs, deps = {}) {
  // Match both the space form (`--embeddings`) and the equals form
  // (`--embeddings=5000`) Commander accepts, so the pnpm allow-build set still
  // widens to onnxruntime-node when a user hand-types the equals form.
  const embeddings = gitnexusArgs.some(
    (a) => a === '--embeddings' || a.startsWith('--embeddings='),
  );
  if (mode === 'gitnexus') return { program: 'gitnexus', args: [...gitnexusArgs] };
  if (mode === 'bun') return { program: 'bunx', args: [NPX_REF, ...gitnexusArgs] };
  if (mode === 'pnpm') {
    return {
      program: 'pnpm',
      args: [...formatPnpmAllowBuildArgs({ embeddings }, deps), 'dlx', NPX_REF, ...gitnexusArgs],
    };
  }
  return { program: 'npx', args: [NPX_REF, ...gitnexusArgs] };
}

module.exports = {
  formatAnalyzeCommand,
  formatBunxCommand,
  formatDocumentationDlxCommand,
  formatPnpmAllowBuildArgs,
  formatPnpmDlxCommand,
  resolveInvocationMode,
  buildRunnerArgv,
  resolveOnPath,
  getNpmMajorVersion,
  NPX_REF,
  PNPM_ALLOW_BUILD_BASE,
};

// Direct-exec entrypoint (#1945): `node run.cjs <gitnexus argsΓÇª>` resolves the
// best available runner (global `gitnexus` ΓåÆ `pnpm dlx` ΓåÆ `bunx` ΓåÆ `npx`) at call time and
// runs it, inheriting stdio and propagating the child's exit code. This lets the
// committed skills and generated AGENTS.md/CLAUDE.md reference ONE stable,
// CLI-neutral command without baking in a package-manager assumption. `gitnexus
// analyze` drops a copy of this file at `.gitnexus/run.cjs`. Skipped on require()
// (the CLI and tests reuse the exports above), so it runs only when invoked as a
// script.
if (require.main === module) {
  const gitnexusArgs = process.argv.slice(2);
  const { program, args } = buildRunnerArgv(resolveInvocationMode(), gitnexusArgs);
  try {
    execFileSync(program, args, {
      stdio: 'inherit',
      windowsHide: true,
      // On Windows, `npx`/`pnpm`/`gitnexus` resolve to `.cmd`/`.ps1`/`.exe`
      // shims (npm, Volta, Corepack, scoop). execFileSync does not do PATHEXT
      // resolution and Node refuses to spawn `.cmd`/`.bat` without a shell
      // (CVE-2024-27980), so a bare program name ENOENTs. A shell lets the OS
      // resolve the shim; POSIX needs no shell (direct PATH lookup works).
      shell: process.platform === 'win32',
    });
  } catch (err) {
    // Make spawn failures (resolved program absent from PATH) self-explanatory
    // instead of a silent exit 1, then propagate the runner's own exit code.
    if (typeof err.status !== 'number') {
      process.stderr.write(`gitnexus runner: could not launch \`${program}\` ΓÇö ${err.message}\n`);
    }
    process.exit(typeof err.status === 'number' ? err.status : 1);
  }
}

"use server";

import { adminAuth, adminDb } from "@/lib/firebase/admin";
import { cookies } from "next/headers";
import { unstable_cache } from "next/cache";
import type {
  AILessonRecommendation,
  AIRecommendationCache,
  GenerateAIRecommendationsResult,
  RecommendationPriority,
  ChildProfile,
  Session,
} from "@/types";

const getCachedLessonLibrary = unstable_cache(
  async () => {
    const lessonsSnap = await adminDb.collection("lessons").get();
    return lessonsSnap.docs.map((d) => {
      const l = d.data();
      return {
        id: d.id,
        lesson_id: l.lesson_id ?? d.id,
        lesson_name: l.lesson_name ?? "",
        level_name: l.level_name ?? "",
        type: l.type ?? "",
        description: l.description ?? "",
        scenario: l.scenario ?? "",
        min_age: l.min_age ?? 0,
        duration_min: l.duration_min ?? 0,
        thumbnail_url: l.thumbnail_url ?? null,
        scene_name: l.scene_name ?? "",
        target_skills: l.target_skills ?? [],
        difficulty_level: l.difficulty_level ?? "",
        prerequisites: l.prerequisites ?? [],
      };
    });
  },
  ["ai-all-lessons"],
  {
    revalidate: 86400, // 24 hours
    tags: ["lessons"],
  }
);
// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const SESSION_COOKIE_NAME = "session";
const GEMINI_MODEL = process.env.GEMINI_MODEL ?? "gemini-2.5-flash";
const MAX_SESSIONS = 3;

// ΓöÇΓöÇΓöÇ Auth helper ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
async function getAuthSession() {
  const cookie = (await cookies()).get(SESSION_COOKIE_NAME)?.value;
  if (!cookie) return null;
  try {
    return await adminAuth.verifySessionCookie(cookie);
  } catch {
    return null;
  }
}

// ΓöÇΓöÇΓöÇ Public Action: ─æß╗ìc cache ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
/**
 * ─Éß╗ìc dß╗» liß╗çu gß╗úi ├╜ ─æ├ú l╞░u trong Firestore (nß║┐u c├│).
 * Kh├┤ng gß╗ìi Gemini. Trß║ú vß╗ü hasNewSessionData=true nß║┐u c├│ session mß╗¢i h╞ín cache.
 */
export async function getCachedAIRecommendations(
  childId: string
): Promise<GenerateAIRecommendationsResult> {
  const auth = await getAuthSession();
  if (!auth) return { success: false, error: "Unauthorized" };

  try {
    // Kiß╗âm tra quyß╗ün truy cß║¡p
    const childDoc = await adminDb.collection("child_profiles").doc(childId).get();
    if (!childDoc.exists) return { success: false, error: "Kh├┤ng t├¼m thß║Ñy hß╗ô s╞í trß║╗" };

    const childData = childDoc.data()!;
    if (childData.expertUid !== auth.uid && auth.role !== "admin") {
      return { success: false, error: "Bß║ín kh├┤ng c├│ quyß╗ün truy cß║¡p hß╗ô s╞í n├áy" };
    }

    // Lß║Ñy 3 session mß╗¢i nhß║Ñt ─æß╗â so khß╗¢p cache
    const latestSessionIds = await getLatestSessionIds(childId);

    // ─Éß╗ìc cache
    const cacheDoc = await adminDb.collection("ai_recommendations").doc(childId).get();
    if (!cacheDoc.exists) {
      return {
        success: true,
        source: "cache",
        childId,
        hasNewSessionData: false,
        recommendations: undefined,
      };
    }

    const cache = cacheDoc.data() as AIRecommendationCache;
    const hasNewSessionData =
      JSON.stringify(latestSessionIds) !== JSON.stringify(cache.basedOnSessionIds);

    return {
      success: true,
      source: "cache",
      childId,
      generatedAt: cache.generatedAt,
      basedOnSessionIds: cache.basedOnSessionIds,
      hasNewSessionData,
      summary: cache.summary,
      recommendations: cache.recommendations,
      insufficientData: cache.insufficientData,
      isDemo: cache.isDemo,
    };
  } catch (err: any) {
    console.error("[getCachedAIRecommendations] error:", err);
    return { success: false, error: err.message };
  }
}

// ΓöÇΓöÇΓöÇ Public Action: tß║ío/l├ám mß╗¢i gß╗úi ├╜ ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
/**
 * Tß║ío mß╗¢i hoß║╖c l├ám mß╗¢i gß╗úi ├╜ b├ái hß╗ìc bß║▒ng Gemini (hoß║╖c Demo Mode).
 * Kß║┐t quß║ú ─æ╞░ß╗úc l╞░u v├áo ai_recommendations/{childId}.
 */
export async function generateAIRecommendations(
  childId: string
): Promise<GenerateAIRecommendationsResult> {
  const auth = await getAuthSession();
  if (!auth) return { success: false, error: "Unauthorized" };

  try {
    // 1. Kiß╗âm tra quyß╗ün
    const childDoc = await adminDb.collection("child_profiles").doc(childId).get();
    if (!childDoc.exists) return { success: false, error: "Kh├┤ng t├¼m thß║Ñy hß╗ô s╞í trß║╗" };

    const childData = childDoc.data()!;
    if (childData.expertUid !== auth.uid && auth.role !== "admin") {
      return { success: false, error: "Bß║ín kh├┤ng c├│ quyß╗ün truy cß║¡p hß╗ô s╞í n├áy" };
    }

    // Lß║Ñy 3 session mß╗¢i nhß║Ñt ΓÇö sß║»p xß║┐p trong memory tr├ính y├¬u cß║ºu Composite Index
    const sessionsSnap = await adminDb
      .collection("sessions")
      .where("child_profile_id", "==", childId)
      .get();

    const sessions = sessionsSnap.docs
      .map((d) => {
        const s = d.data();
        return {
          id: d.id,
          lesson_id: s.lesson_id ?? "",
          lesson_name: s.lesson_name ?? "",
          level_name: s.level_name ?? "",
          type: s.type ?? "",
          score: s.score ?? 0,
          completion_status: s.completion_status ?? "",
          duration: s.duration ?? 0,
          quest_logs: s.quest_logs ?? [],
          auto_alerts: s.auto_alerts ?? [],
          behavior_logs: s.behavior_logs ?? [],
          evaluation: s.evaluation ?? "",
          notes: s.notes ?? "",
          start_time: s.start_time ?? "",
          finish_time: s.finish_time ?? "",
        };
      })
      .sort((a, b) => {
        // Mß╗¢i nhß║Ñt l├¬n ─æß║ºu
        const ta = a.finish_time ? new Date(a.finish_time).getTime() : 0;
        const tb = b.finish_time ? new Date(b.finish_time).getTime() : 0;
        return tb - ta;
      })
      .slice(0, MAX_SESSIONS);

    const basedOnSessionIds = sessions.map((s) => s.id);
    const insufficientData = sessions.length < MAX_SESSIONS;

    // 3. Lß║Ñy danh mß╗Ñc b├ái hß╗ìc (─æ├ú ─æ╞░ß╗úc cache ngß║ºm 24h) v├á lß╗ìc theo ─æß╗Ö tuß╗òi
    const allLessons = await getCachedLessonLibrary();
    const childAge: number = childData.age ?? 0;
    // Lß╗ìc b├ái hß╗ìc ph├╣ hß╗úp tuß╗òi ─æß╗â giß║úm k├¡ch th╞░ß╗¢c payload
    const eligibleLessons = allLessons.filter((l) => l.min_age <= childAge);
    const lessonIds = new Set(eligibleLessons.map((l) => l.id));

    // 4. ß║¿n danh h├│a hß╗ô s╞í trß║╗ ΓÇö chß╗ë giß╗» c├íc tr╞░ß╗¥ng l├óm s├áng
    // 4. ß║¿n danh h├│a hß╗ô s╞í trß║╗ ΓÇö chß╗ë giß╗» c├íc tr╞░ß╗¥ng l├óm s├áng v├á mß╗Ñc ti├¬u
    const anonymizedChild = {
      age: childData.age,
      gender: childData.gender,
      condition: childData.condition,
      sound_sensitivity: childData.sound_sensitivity,
      attention_span_min: childData.attention_span_min,
      anxiety_triggers: childData.anxiety_triggers,
      diagnosis_notes: childData.diagnosis_notes,
      sessionCount: childData.sessionCount,
      goals: childData.goals || [],
    };

    // Chuß║⌐n bß╗ï sessions cho AI: X├│a lesson_id ─æß╗â triß╗çt ti├¬u khß║ú n─âng AI nhß║»c ─æß║┐n ID trong c├óu v─ân
    const lessonMapAll = new Map(allLessons.map((l) => [l.id, l]));
    const anonymizedSessions = sessions.map((s) => {
      const lessonInfo = lessonMapAll.get(s.lesson_id);
      const { lesson_id, ...rest } = s; // X├│a lesson_id
      return {
        ...rest,
        lesson_name: s.lesson_name || lessonInfo?.lesson_name || "B├ái hß╗ìc VR",
      };
    });

    // 5. Nß║┐u thiß║┐u API key ΓåÆ Demo Mode
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      const demoResult = buildDemoRecommendations(
        childId,
        auth.uid,
        eligibleLessons,
        sessions,
        basedOnSessionIds,
        insufficientData
      );
      await saveCache(demoResult);
      return { ...toResult(demoResult), source: "demo" };
    }

    // 6. Gß╗ìi Gemini 2.5 Flash
    const geminiResult = await callGemini(
      apiKey,
      anonymizedChild,
      anonymizedSessions,
      eligibleLessons,
      childId,
      auth.uid,
      basedOnSessionIds,
      insufficientData
    );

    // 7. Validate: lessonId phß║úi tß╗ôn tß║íi trong Firestore lessons
    const lessonMap = new Map(eligibleLessons.map((l) => [l.id, l]));

    // H├ám dß╗ìn dß║╣p chuß╗ùi: X├│a m├ú ID trong ngoß║╖c, hoß║╖c thay ID bß║▒ng t├¬n b├ái hß╗ìc
    const cleanAIText = (text: string) => {
      if (!text) return text;
      let res = text;
      eligibleLessons.forEach((l) => {
        const id = l.lesson_id || l.id;
        const name = l.lesson_name || "b├ái hß╗ìc n├áy";
        if (id) {
          // X├│a "(ID)" hoß║╖c " (ID)"
          res = res.replace(new RegExp(`\\s*\\(${id}\\)`, "g"), "");
          // Thay ID ─æß╗⌐ng ─æß╗Öc lß║¡p th├ánh t├¬n b├ái hß╗ìc
          res = res.replace(new RegExp(id, "g"), name);
        }
      });
      return res;
    };

    geminiResult.summary = cleanAIText(geminiResult.summary);

    const validRecs = (geminiResult.recommendations ?? [])
      .filter((r) => {
        if (!lessonIds.has(r.lessonId)) {
          console.warn(`[AI] Loß║íi bß╗Å b├ái kh├┤ng tß╗ôn tß║íi: ${r.lessonId}`);
          return false;
        }
        if (r.confidence < 0 || r.confidence > 1) return false;
        if (!["high", "medium", "low"].includes(r.priority)) return false;
        return true;
      })
      .map((r) => {
        const matchingLesson = lessonMap.get(r.lessonId);
        return {
          ...r,
          reason: cleanAIText(r.reason),
          expectedBenefit: cleanAIText(r.expectedBenefit),
          specialistNotes: cleanAIText(r.specialistNotes),
          thumbnailUrl: matchingLesson?.thumbnail_url ?? null,
          sceneName: matchingLesson?.scene_name ?? "",
          difficultyLevel: matchingLesson?.difficulty_level ?? "Ch╞░a x├íc ─æß╗ïnh",
        };
      });

    if (validRecs.length === 0) {
      return {
        success: false,
        error: "AI kh├┤ng trß║ú vß╗ü b├ái hß╗ìc hß╗úp lß╗ç n├áo. Vui l├▓ng thß╗¡ lß║íi.",
      };
    }

    const finalCache: AIRecommendationCache = {
      ...geminiResult,
      recommendations: validRecs,
    };

    await saveCache(finalCache);
    return { ...toResult(finalCache), source: "gemini" };
  } catch (err: any) {
    console.error("[generateAIRecommendations] error:", err);
    return { success: false, error: err.message ?? "─É├ú c├│ lß╗ùi xß║úy ra" };
  }
}

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function getLatestSessionIds(childId: string): Promise<string[]> {
  // Kh├┤ng d├╣ng orderBy ─æß╗â tr├ính y├¬u cß║ºu Composite Index tr├¬n Firestore
  const snap = await adminDb
    .collection("sessions")
    .where("child_profile_id", "==", childId)
    .get();

  return snap.docs
    .map((d) => ({
      id: d.id,
      finish_time: d.data().finish_time ?? "",
    }))
    .sort((a, b) => {
      const ta = a.finish_time ? new Date(a.finish_time).getTime() : 0;
      const tb = b.finish_time ? new Date(b.finish_time).getTime() : 0;
      return tb - ta;
    })
    .slice(0, MAX_SESSIONS)
    .map((s) => s.id);
}

async function saveCache(cache: AIRecommendationCache) {
  await adminDb
    .collection("ai_recommendations")
    .doc(cache.childId)
    .set(cache, { merge: false });
}

function toResult(cache: AIRecommendationCache): GenerateAIRecommendationsResult {
  return {
    success: true,
    childId: cache.childId,
    generatedAt: cache.generatedAt,
    basedOnSessionIds: cache.basedOnSessionIds,
    hasNewSessionData: false,
    summary: cache.summary,
    recommendations: cache.recommendations,
    insufficientData: cache.insufficientData,
    isDemo: cache.isDemo,
  };
}

// ΓöÇΓöÇΓöÇ Gemini Caller ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
