}

"use server";

import { adminDb } from "@/lib/firebase/admin";
import { Session } from "@/types";

// Utility to fetch sessions across multiple field names
async function fetchSessionsForChild(childId: string) {
  const targetId = childId.trim();
  const snapshot = await adminDb.collection("sessions").orderBy("start_time", "desc").limit(500).get();
  
  const matches = snapshot.docs.filter(doc => {
    const data = doc.data();
    return data.child_profile_id === targetId || data.child_id === targetId || data.childId === targetId;
  });

  return matches.map(doc => ({ id: doc.id, ...doc.data() } as Session));
}

/**
 * Shared Analytics Action for both Parent and Expert Dashboards
 * Focuses on the LAST 5 SESSIONS with high-sensitivity weights
 */
export async function getChildAlertStats(childId: string) {
  try {
    const sessions = await fetchSessionsForChild(childId);
    
    // Focus on LAST 5 SESSIONS for maximum responsiveness
    const recentSessions = sessions.slice(0, 5);
    const totalRecent = recentSessions.length || 1;
    const totalPenalties = { chudoong: 0, tutin: 0, taptrung: 0, ondinh: 0, binhtinh: 0 };

    recentSessions.forEach((s: Session) => {
      const alerts = s.auto_alerts || [];
      
      // 1. CHß╗ª ─Éß╗ÿNG (idle - Low: -30─æ mß╗ùi 5s, max -100─æ)
      const idleDuration = alerts.filter((a: Record<string, any>) => a.type === 'idle').reduce((acc: number, a: Record<string, any>) => acc + (a.duration_sec || 0), 0);
      totalPenalties.chudoong += Math.min(100, Math.floor(idleDuration / 5) * 30);

      // 2. Tß╗░ TIN (hesitation - Low: -60─æ/lß║ºn, max -100─æ)
      const hesitationCount = alerts.filter((a: Record<string, any>) => a.type === 'hesitation').length;
      totalPenalties.tutin += Math.min(100, hesitationCount * 60);

      // 3. Tß║¼P TRUNG (distraction - Medium: -50─æ mß╗ùi 5s, max -100─æ)
      const distractionDuration = alerts.filter((a: Record<string, any>) => a.type === 'distraction').reduce((acc: number, a: Record<string, any>) => acc + (a.duration_sec || 0), 0);
      totalPenalties.taptrung += Math.min(100, Math.floor(distractionDuration / 5) * 50);

      // 4. ß╗öN ─Éß╗èNH (stimming_proxy - Medium: -80─æ/lß║ºn, max -100─æ)
      const stimmingCount = alerts.filter((a: Record<string, any>) => a.type === 'stimming_proxy').length;
      totalPenalties.ondinh += Math.min(100, stimmingCount * 80);

      // 5. B├îNH T─¿NH (freeze/meltdown - High: -150─æ/lß║ºn, max -100─æ -> thß╗▒c tß║┐ l├á vß║┐ tr├íi sß║╜ bß╗ï cap ß╗ƒ 100)
      const stressCount = alerts.filter((a: Record<string, any>) => 
        a.type === 'freeze' || a.type === 'meltdown_proxy' || a.group === 'stress_overwhelm'
      ).length;
      totalPenalties.binhtinh += Math.min(100, stressCount * 150);
    });

    const radarData = [
      { subject: 'Tß║¼P TRUNG', A: Math.max(0, 100 - (totalPenalties.taptrung / totalRecent)), fullMark: 100 },
      { subject: 'B├îNH T─¿NH', A: Math.max(0, 100 - (totalPenalties.binhtinh / totalRecent)), fullMark: 100 },
      { subject: 'CHß╗ª ─Éß╗ÿNG', A: Math.max(0, 100 - (totalPenalties.chudoong / totalRecent)), fullMark: 100 },
      { subject: 'Tß╗░ TIN', A: Math.max(0, 100 - (totalPenalties.tutin / totalRecent)), fullMark: 100 },
      { subject: 'ß╗öN ─Éß╗èNH', A: Math.max(0, 100 - (totalPenalties.ondinh / totalRecent)), fullMark: 100 },
    ];

    return { success: true, radarData };
  } catch (error: any) {
    console.error("Error fetching child alert stats:", error);
    return { success: false, error: error.message };
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { cookies } from "next/headers";
import { adminAuth, adminDb } from "@/lib/firebase/admin";
import { redirect } from "next/navigation";
import { QueryDocumentSnapshot, DocumentData } from "firebase-admin/firestore";
import { getCollectionName } from "@/lib/utils/roles";

const SESSION_COOKIE_NAME = "session";
const EXPIRES_IN = 60 * 60 * 24 * 5 * 1000; // 5 days

// getCollectionName moved to @/lib/utils/roles.ts to satisfy Next.js 15 Server Action async rule.

export async function createSession(idToken: string) {
  try {
    // 1. Verify the token
    const decodedIdToken = await adminAuth.verifyIdToken(idToken);
    const uid = decodedIdToken.uid;
    const email = decodedIdToken.email;

    // 2. [RECOVERY] Hardcode Admin Role for specific email
    let role = decodedIdToken.role;
    const ADMIN_SEED_EMAIL = process.env.ADMIN_SEED_EMAIL;
    if (ADMIN_SEED_EMAIL && email === ADMIN_SEED_EMAIL) {
      role = "admin";
      await adminDb.collection("system_admins").doc(uid).set({
        role: "admin",
        email: email,
        updatedAt: new Date().toISOString()
      }, { merge: true });
      await adminAuth.setCustomUserClaims(uid, { role: "admin" });
    }

    if (!role) role = "parent";
    const collectionName = getCollectionName(role);

    // 3. Sync Roles: Check Firestore first
    let userDoc = await adminDb.collection(collectionName).doc(uid).get();
    
    // Fallback vß╗¢t tß╗½ users c┼⌐
    if (!userDoc.exists) {
      const oldDoc = await adminDb.collection("users").doc(uid).get();
      if (oldDoc.exists) {
        userDoc = oldDoc;
      }
    }

    if (userDoc.exists) {
      // Use Firestore role as source of truth
      role = userDoc.data()?.role || role;
      const targetCol = getCollectionName(role);
      
      // Sync email
      const updates: Record<string, any> = {};
      if (!userDoc.data()?.email || userDoc.data()?.email !== email) updates.email = email || "";
      
      if (Object.keys(updates).length > 0) {
        await adminDb.collection(targetCol).doc(uid).update(updates);
      }
    } else {
      // Auto-Migration/New User Logic
      await adminDb.collection(collectionName).doc(uid).set({
        role: role,
        email: email || "",
        updatedAt: new Date().toISOString()
      });
    }

    // 4. Update Custom Claims if they don't match Firestore
    if (decodedIdToken.role !== role) {
      await adminAuth.setCustomUserClaims(uid, { role });
    }
    
    // Only process if the user recently signed in
    if (new Date().getTime() / 1000 - decodedIdToken.auth_time < 5 * 60) {
      // Create session cookie
      const cookie = await adminAuth.createSessionCookie(idToken, {
        expiresIn: EXPIRES_IN,
      });

      const options = {
        name: SESSION_COOKIE_NAME,
        value: cookie,
        maxAge: EXPIRES_IN,
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        path: "/",
      };

      (await cookies()).set(options);
      
      return { success: true, role };
    }
    return { success: false, error: "Recent sign in required" };
  } catch (error) {
    console.error("Session creation error", error);
    return { success: false, error: "Unauthorized" };
  }
}

export async function removeSession() {
  const sessionCookie = (await cookies()).get(SESSION_COOKIE_NAME)?.value;
  if (!sessionCookie) return { success: true };

  try {
    const decodedClaims = await adminAuth.verifySessionCookie(sessionCookie);
    await adminAuth.revokeRefreshTokens(decodedClaims.sub);
  } catch (error) {
    // Ignore error if cookie is invalid
  }

  (await cookies()).delete(SESSION_COOKIE_NAME);
  redirect("/");
}

export async function setParentRole(uid: string) {
  try {
    // Update both Firestore and Auth Claims
    const userRef = adminDb.collection("parents").doc(uid);
    const userDoc = await userRef.get();
    
    // If user already has a role (like admin), DON'T overwrite it to parent
    if (userDoc.exists && userDoc.data()?.role) {
      console.log(`User ${uid} already has role ${userDoc.data()?.role}, skipping parent auto-assign.`);
      return { success: true, role: userDoc.data()?.role };
    }

    await userRef.set({
      role: "parent",
      updatedAt: new Date().toISOString()
    }, { merge: true });

    await adminAuth.setCustomUserClaims(uid, { role: "parent" });
    return { success: true, role: "parent" };
  } catch (error) {
    console.error("Error setting custom claim", error);
    return { success: false };
  }
}

export async function updateUserRole(uid: string, role: string) {
  try {
    const colName = getCollectionName(role);
    await adminDb.collection(colName).doc(uid).set({
      role: role,
      updatedAt: new Date().toISOString()
    }, { merge: true });
    
    await adminAuth.setCustomUserClaims(uid, { role });
    return { success: true };
  } catch (error: any) {
    console.error("Error updating user role:", error);
    return { success: false, error: error.message };
  }
}

