export async function getChildDashboardAnalytics(childId: string) {
  const session = await getSession();
  if (!session) return { success: false, error: "Unauthorized" };

  try {
    const sessions = await fetchSessionsForChild(childId);
    if (sessions.length === 0) return { success: true, radarData: [], trendData: [] };

    // 1. Calculate Radar Data
    let totalQuests = 0;
    let successfulQuests = 0;
    let zeroHintQuests = 0;
    let totalResponseTime = 0;
    let totalScore = 0;

    sessions.forEach((s: Session) => {
      const logs = s.quest_logs || [];
      totalQuests += logs.length;
      totalScore += (s.score || 0);
      
      logs.forEach((log: QuestLog) => {
        if (log.completion_status === "success") successfulQuests++;
        if ((log.hints_physical || 0) + (log.hints_verbal || 0) + (log.hints_visual || 0) === 0) {
          zeroHintQuests++;
        }
        totalResponseTime += (log.response_time || 0);
      });
    });

    const avgAccuracy = totalQuests > 0 ? (successfulQuests / totalQuests) * 100 : 0;
    const avgIndependence = totalQuests > 0 ? (zeroHintQuests / totalQuests) * 100 : 0;
    const avgResponseTime = totalQuests > 0 ? totalResponseTime / totalQuests : 0;
    const avgCompletion = totalScore / sessions.length;
    
    // 1. Calculate Radar Data (Strictly follow RADAR_CHART_METRICS.md - Focus on LAST 5 SESSIONS)
    const recentSessions = sessions.slice(0, 5);
    const totalRecent = recentSessions.length || 1;
    const totalPenalties = { chudoong: 0, tutin: 0, taptrung: 0, ondinh: 0, binhtinh: 0 };

    recentSessions.forEach((s: Session) => {
      const alerts = s.auto_alerts || [];
      
      // 1. CHß╗ª ─Éß╗ÿNG (idle - Low: -30─æ mß╗ùi 5s, max -100─æ)
      const idleDur = alerts.filter((a: Record<string, any>) => a.type === 'idle').reduce((acc: number, a: Record<string, any>) => acc + (a.duration_sec || 0), 0);
      totalPenalties.chudoong += Math.min(100, Math.floor(idleDur / 5) * 30);

      // 2. Tß╗░ TIN (hesitation - Low: -60─æ/lß║ºn, max -100─æ)
      const hesitationCount = alerts.filter((a: Record<string, any>) => a.type === 'hesitation').length;
      totalPenalties.tutin += Math.min(100, hesitationCount * 60);

      // 3. Tß║¼P TRUNG (distraction - Medium: -50─æ mß╗ùi 5s, max -100─æ)
      const distractionDur = alerts.filter((a: Record<string, any>) => a.type === 'distraction').reduce((acc: number, a: Record<string, any>) => acc + (a.duration_sec || 0), 0);
      totalPenalties.taptrung += Math.min(100, Math.floor(distractionDur / 5) * 50);

      // 4. ß╗öN ─Éß╗èNH (stimming_proxy - Medium: -80─æ/lß║ºn, max -100─æ)
      const stimmingCount = alerts.filter((a: Record<string, any>) => a.type === 'stimming_proxy').length;
      totalPenalties.ondinh += Math.min(100, stimmingCount * 80);

      // 5. B├îNH T─¿NH (freeze/meltdown - High: -150─æ/lß║ºn, max -100─æ)
      const stressCount = alerts.filter((a: Record<string, any>) => 
        a.type === 'freeze' || a.type === 'meltdown_proxy' || a.group === 'stress_overwhelm'
      ).length;
      totalPenalties.binhtinh += Math.min(100, stressCount * 150);
    });

    const radarData = [
      { subject: 'Tß║¼P TRUNG', A: Math.max(0, 100 - (totalPenalties.taptrung / totalRecent)), fullMark: 100 },
      { subject: 'B├îNH T─¿NH', A: Math.max(0, 100 - (totalPenalties.binhtinh / totalRecent)), fullMark: 100 },
      { subject: 'CHß╗ª ─Éß╗ÿNG', A: Math.max(0, 100 - (totalPenalties.chudoong / totalRecent)), fullMark: 100 },
      { subject: 'Tß╗░ TIN', A: Math.max(0, 100 - (totalPenalties.tutin / totalRecent)), fullMark: 100 },
      { subject: 'ß╗öN ─Éß╗èNH', A: Math.max(0, 100 - (totalPenalties.ondinh / totalRecent)), fullMark: 100 },
    ];

    // 2. Trend Data (Last 10 sessions)
    const trendData = sessions.slice(0, 10).reverse().map((s: Session) => {
      let dateStr = "";
      if ((s.start_time as any)?.toDate) {
        dateStr = (s.start_time as any).toDate().toLocaleDateString("vi-VN", { day: 'numeric', month: 'short' });
      } else {
        const rawDate = s.start_time || (s as any).startTime;
        if (typeof rawDate === 'string') {
          const [y, m, d] = rawDate.split('T')[0].split('-');
          dateStr = `${d} thg ${m}`;
        }
      }
      return {
        date: dateStr || "---",
        score: s.score || 0,
        duration: Math.round((s.duration || 0) / 60)
      };
    });

    return { success: true, radarData, trendData };
  } catch (error: any) {
    console.error("Error calculating dashboard analytics:", error);
    return { success: false, error: error.message };
  }
}

export async function getChildHeatmapData(childId: string) {
  const session = await getSession();
