        setNewAdmin({ name: "", email: "", password: "", phone: "" });
        setTimeout(() => {
          setCreateModal(false);
          fetchData();
        }, 1500);
      } else {
        setMessage({ text: res.error || "C├│ lß╗ùi xß║úy ra", type: "error" });
      }
    } catch (err) {
      console.error(err);
      setMessage({ text: "Lß╗ùi hß╗ç thß╗æng", type: "error" });
    } finally {
      setCreating(false);
    }
  };

  const filteredAdmins = admins.filter(a => 
