"use client";

import React, { useState, useRef } from "react";
import { AlertCircle, ChevronRight, Loader2, CheckCircle2 } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { pairWithDevice } from "@/lib/firebase/rtdb";
import { useAuth } from "@/contexts/AuthContext";

interface VRPairingFormProps {
  childId?: string;
}

export default function VRPairingForm({ childId }: VRPairingFormProps) {
  const [pin, setPin] = useState(["", "", "", "", "", ""]);
  const [status, setStatus] = useState<"idle" | "verifying" | "success" | "error">("idle");
  const [errorMsg, setErrorMsg] = useState("");
  const inputs = useRef<(HTMLInputElement | null)[]>([]);
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = useAuth();

  const handleChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newPin = [...pin];
    newPin[index] = value.slice(-1);
    setPin(newPin);
    if (value && index < 5) {
      inputs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === "Backspace" && !pin[index] && index > 0) {
      inputs.current[index - 1]?.focus();
    }
  };

  const handleVerify = async () => {
    if (pin.some(digit => !digit)) return;

    setStatus("verifying");
    setErrorMsg("");

    const pinCode = pin.join("");

    try {
      const { pin: pairedPin } = await pairWithDevice(pinCode, childId || "", user?.uid || "");

      setStatus("success");
      setTimeout(() => {
        const current = new URLSearchParams(searchParams.toString());
        current.set("vr", "connected");
        current.set("pin", pairedPin); // Chß╗ë l╞░u pin, session sß║╜ ─æ╞░ß╗úc tß║ío khi bß║Ñm Start Lesson
        current.delete("session"); // Xo├í session c┼⌐ (nß║┐u c├│)
        router.push(`/dashboard/expert/connection?${current.toString()}`);
      }, 1500);
    } catch (err: any) {
      console.error("VRPairingForm error:", err);
      setStatus("error");
      setErrorMsg(err.message || "Lß╗ùi kß║┐t nß╗æi. Vui l├▓ng thß╗¡ lß║íi.");
    }
  };

  const isComplete = pin.every(d => d !== "");

  return (
    <div className="w-full max-w-sm space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="flex flex-col items-center gap-6">
        {/* 6 ├┤ nhß║¡p PIN */}
        <div className="flex justify-center gap-3">
          {pin.map((digit, i) => (
            <input
              key={i}
              ref={(el) => { inputs.current[i] = el; }}
              type="text"
              inputMode="numeric"
              maxLength={1}
              value={digit}
              onChange={(e) => handleChange(i, e.target.value)}
              onKeyDown={(e) => handleKeyDown(i, e)}
              disabled={status === "verifying" || status === "success"}
              className={`w-10 h-14 text-center text-xl font-black bg-white dark:bg-zinc-900 border-2 rounded-xl outline-none transition-all
                ${status === "error" ? "border-red-400 focus:ring-red-500/10" : "border-zinc-100 dark:border-zinc-800 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10"}
                ${status === "success" ? "border-emerald-400" : ""}
              `}
            />
          ))}
        </div>

        {/* Th├┤ng b├ío trß║íng th├íi */}
        {status === "error" && (
          <div className="flex items-center gap-2 text-red-500 animate-in fade-in">
            <AlertCircle size={14} />
            <span className="text-[11px] font-bold uppercase tracking-widest">{errorMsg}</span>
          </div>
        )}
        {status === "success" && (
          <div className="flex items-center gap-2 text-emerald-500 animate-in fade-in">
            <CheckCircle2 size={14} />
            <span className="text-[11px] font-bold uppercase tracking-widest">Gh├⌐p nß╗æi th├ánh c├┤ng!</span>
          </div>
        )}

        {/* N├║t bß║Ñm */}
        <button
          onClick={handleVerify}
          disabled={!isComplete || status === "verifying" || status === "success"}
          className={`w-full py-3.5 rounded-[1.5rem] font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all ${
            !isComplete
              ? "bg-zinc-100 text-zinc-400 cursor-not-allowed dark:bg-zinc-800"
              : "bg-zinc-900 text-white hover:bg-blue-600 dark:bg-white dark:text-zinc-900 dark:hover:bg-blue-600 dark:hover:text-white shadow-xl shadow-zinc-500/10"
          }`}
        >
          {status === "verifying" ? (
            <Loader2 size={20} className="animate-spin" />
          ) : status === "success" ? (
            <CheckCircle2 size={20} className="text-emerald-400" />
          ) : (
            <>
              <span>Kß║┐t nß╗æi thiß║┐t bß╗ï</span>
              <ChevronRight size={18} />
            </>
          )}
        </button>
      </div>

      {/* H╞░ß╗¢ng dß║½n tß╗½ng b╞░ß╗¢c */}
      <div className="space-y-6 pt-6 border-t border-zinc-50 dark:border-zinc-800">
        {[
          "Khß╗ƒi chß║íy ß╗⌐ng dß╗Ñng VRA tr├¬n thiß║┐t bß╗ï VR cß╗ºa bß║ín.",
          "M├ú PIN gß╗ôm 6 chß╗» sß╗æ sß║╜ xuß║Ñt hiß╗çn tr├¬n m├án h├¼nh ch├¡nh cß╗ºa thiß║┐t bß╗ï VR.",
          "Nhß║¡p m├ú ─æ├│ v├áo c├íc ├┤ ph├¡a tr├¬n ─æß╗â thiß║┐t lß║¡p kß║┐t nß╗æi ─æiß╗üu khiß╗ân thß╗¥i gian thß╗▒c.",
        ].map((text, i) => (
          <div key={i} className="flex items-start gap-4">
            <div className="w-8 h-8 bg-blue-50 dark:bg-blue-500/10 rounded-full flex items-center justify-center text-blue-600 text-xs font-black shrink-0">
              {i + 1}
            </div>
            <p className="text-sm font-medium text-zinc-500 dark:text-zinc-400">{text}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Smartphone, Cast, CheckCircle2, Loader2, X, AlertCircle } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { pairWithDevice } from "@/lib/firebase/rtdb";
import { useAuth } from "@/contexts/AuthContext";

interface VRPairingOverlayProps {
  onConnect?: () => void;
  onSkip?: () => void;
  childId?: string;
  childName: string;
}

export default function VRPairingOverlay({ onConnect, onSkip, childId, childName }: VRPairingOverlayProps) {
  const [pin, setPin] = useState("");
  const [status, setStatus] = useState<"idle" | "connecting" | "success" | "error">("idle");
  const [errorMsg, setErrorMsg] = useState("");
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = useAuth();

  const handleConnect = async () => {
    if (pin.length < 3) return;
    
    setStatus("connecting");
    setErrorMsg("");

    try {
      const { pin: pairedPin } = await pairWithDevice(pin, childId || "", user?.uid || "");

      setStatus("success");
      setTimeout(() => {
        const current = new URLSearchParams(Array.from(searchParams.entries()));
        current.set("vr", "connected");
        current.set("pin", pairedPin); // Chß╗ë l╞░u pin, session sß║╜ ─æ╞░ß╗úc tß║ío khi bß║Ñm StartLesson
        current.delete("session");
        router.push(`/dashboard/expert?${current.toString()}`);
        onConnect?.();
      }, 1500);
    } catch (error: any) {
      console.error("Pairing Error:", error);
      setStatus("error");
      setErrorMsg(error.message || "Lß╗ùi khi kß║┐t nß╗æi vß╗¢i server K├¡nh VR.");
    }
  };

  const handleSkip = () => {
    const current = new URLSearchParams(Array.from(searchParams.entries()));
    current.set("vr", "skipped");
    router.push(`/dashboard/expert?${current.toString()}`);
    onSkip?.();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-zinc-950/80 backdrop-blur-md animate-in fade-in duration-500">
      <div className="bg-white dark:bg-zinc-900 w-full max-w-[340px] rounded-[2rem] overflow-hidden shadow-2xl border border-zinc-100 dark:border-zinc-800 animate-in zoom-in-95 duration-500">
        
        {/* Header Illustration */}
        <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 text-white text-center relative overflow-hidden">
          <div className="absolute top-0 right-0 -translate-y-1/4 translate-x-1/4 w-32 h-32 bg-white/10 rounded-full blur-3xl" />
