            description="Bß║¡t/Tß║»t chß║┐ ─æß╗Ö tß╗▒ ─æß╗Öng nhß║»c nhß╗ƒ hoß║╖c hiß╗ân thß╗ï nh├íy viß╗ün tß╗½ hß╗ç thß╗æng."
            icon={<Zap size={16} />}
            checked={params.actions.enable_auto_hint}
            onChange={v => setActions({ enable_auto_hint: v })}
          />
          {/* Visual Guidance toggle */}
          <ToggleRow
            label="Hiß╗çu ß╗⌐ng viß╗ün ph├ít s├íng (Outline)"
            description="Tß║»t khi trß║╗ nhß║íy cß║úm vß╗¢i ├ính s├íng nhß║Ñp nh├íy."
            icon={params.actions.enable_visual_guidance ? <Eye size={16} /> : <EyeOff size={16} />}
            checked={params.actions.enable_visual_guidance}
            onChange={v => setActions({ enable_visual_guidance: v })}
          />
          {/* Bubble Hints toggle */}
          <ToggleRow
            label="Bong b├│ng c├óu hß╗Åi (Bubble Hints)"
            description="Tß║»t nß║┐u trß║╗ bß╗ï ph├ón t├óm bß╗ƒi th├┤ng tin nß╗òi."
            icon={<MessageCircle size={16} />}
            checked={params.actions.enable_bubble_hints}
            onChange={v => setActions({ enable_bubble_hints: v })}
          />
          {/* Action Reminder Cycle */}
          <SentinelSlider
            label="Chu kß╗│ nhß║»c nhß╗ƒ tß╗▒ ─æß╗Öng (gi├óy)"
            description="Khoß║úng c├ích giß╗»a c├íc lß║ºn hß╗ç thß╗æng tß╗▒ nhß║»c nß║┐u trß║╗ kh├┤ng phß║ún hß╗ôi."
            value={params.actions.action_reminder_cycle}
