            onChange={v => setActions({ action_reminder_cycle: v })}
          />
          {/* Gaze Cone Angle */}
          <SentinelSlider
            label="G├│c mß╗ƒ n├│n thß╗ï gi├íc (─æß╗Ö)"
            description="G├│c mß╗ƒ to├án phß║ºn cß╗ºa h├¼nh n├│n thß╗ï gi├íc (tß╗½ 5 ─æß║┐n 15 ─æß╗Ö) d├╣ng ─æß╗â theo d├╡i ─æß╗Ö tß║¡p trung ├ính nh├¼n."
            value={params.actions.gaze_cone_angle}
            min={5}
            max={15}
            systemDefault={10}
