          />
        </Section>

        {/* ΓöÇΓöÇ Dß║íng b├ái: Quiz ΓöÇΓöÇ */}
        <Section icon={<BookOpen size={16} className="text-blue-500" />} title="B├ái trß║»c nghiß╗çm (Quiz)">
          <SentinelSlider
            label="Trß╗à giß╗¢i thiß╗çu Quiz (gi├óy)"
