          <SentinelSlider
            label="Khoß║úng dß╗½ng giß╗»a c├íc ├óm thanh (gi├óy)"
            description="Khoß║úng c├ích giß╗»a c├óu hß╗Åi v├á ├óm thanh tiß║┐ng k├¬u con vß║¡t."
            value={params.quiz.quiz_sound_gap}
            min={0}
            max={5}
            systemDefault={0.5}
            step={0.1}
