      case "Kh├│": return "text-rose-600 bg-rose-100 dark:text-rose-400 dark:bg-rose-500/10 border-rose-200 dark:border-rose-500/20";
      default: return "text-zinc-600 bg-zinc-100 dark:text-zinc-400 dark:bg-zinc-800 border-zinc-200 dark:border-zinc-700";
