              </div>
            </div>
          );
        })}
      </div>

      {/* Modal Popup Cß║Ñu h├¼nh c├óu mß║½u */}
      {customizeLevel && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-100 dark:border-zinc-800 rounded-[2rem] shadow-2xl max-w-3xl w-full max-h-[85vh] flex flex-col overflow-hidden transform transition-all scale-100 duration-350 ease-out">
            {/* Header Modal */}
            <div className="p-6 border-b border-zinc-100 dark:border-zinc-800 flex items-center justify-between bg-zinc-50/50 dark:bg-zinc-900/50">
              <div className="space-y-1">
                <h3 className="text-lg font-black text-zinc-900 dark:text-white uppercase tracking-wide">
                  T├╣y chß╗ënh mß║½u c├óu nhanh
                </h3>
                <p className="text-xs text-zinc-500 dark:text-zinc-400 font-medium">
                  B├ái hß╗ìc: <span className="font-extrabold uppercase text-blue-600 dark:text-blue-400">{customizeLevel.lesson_name}</span> ΓÇö Cß║Ñp {customizeLevel.level_index}: {customizeLevel.level_name}
                </p>
              </div>
              <button
                onClick={() => {
                  setCustomizeLevel(null);
                  setSaveStatus({});
                }}
                className="p-2 hover:bg-zinc-200 dark:hover:bg-zinc-800 rounded-full transition-colors"
                title="─É├│ng cß╗¡a sß╗ò"
              >
                <X size={20} className="text-zinc-500 dark:text-zinc-400" />
              </button>
            </div>

            {/* Content Modal */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {/* Cß║únh b├ío h╞░ß╗¢ng dß║½n */}
              <div className="p-4 bg-blue-500/5 border border-blue-500/10 rounded-2xl flex gap-3 text-xs text-blue-600 dark:text-blue-400 font-medium">
                <Info size={16} className="shrink-0 mt-0.5" />
                <div>
                  <p className="font-bold uppercase tracking-wider mb-1">H╞░ß╗¢ng dß║½n chß╗ënh sß╗¡a mß║½u c├óu</p>
                  <p>C├íc c├óu thoß║íi n├áy sß║╜ ─æ╞░ß╗úc nß║íp ri├¬ng cho b├⌐ <strong>{child?.name}</strong>. Khi chß║íy b├ái hß╗ìc VR, bß║úng ─æiß╗üu khiß╗ân sß║╜ tß╗▒ ─æß╗Öng lß╗ìc c├íc c├óu thoß║íi n├áy theo tß╗½ng nhiß╗çm vß╗Ñ (Quest) t╞░╞íng ß╗⌐ng ─æß╗â gi├ío vi├¬n click gß╗¡i nhanh.</p>
                </div>
              </div>

              {/* Danh s├ích nhiß╗çm vß╗Ñ (Quests) */}
              <div className="space-y-6">
                {(() => {
                  const levelPhrases = getLevelPhrases(customizeLevel);
                  const quests = customizeLevel.quests || [];
                  
                  return quests.map((q, idx) => {
                    const questKey = q.id || q.title || `quest_${idx}`;
                    const list = levelPhrases[questKey] || [];

                    return (
                      <div 
                        key={questKey} 
                        className="space-y-3 bg-zinc-50/50 dark:bg-zinc-950/20 p-5 rounded-2xl border border-zinc-150 dark:border-zinc-800/80"
                      >
                        <div className="flex items-center justify-between">
