                        {list.length === 0 && (
                          <p className="text-xs text-zinc-400 italic py-1 font-medium pl-1">Ch╞░a c├│ c├óu thoß║íi mß║½u n├áo ─æ╞░ß╗úc thiß║┐t lß║¡p.</p>
