          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { PlayCircle, Loader2, AlertCircle, CheckCircle2 } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { startLessonOnDevice } from "@/lib/firebase/rtdb";
import { useAuth } from "@/contexts/AuthContext";

interface StartLessonButtonProps {
  /** Document ID tr├¬n Firestore ΓÇö ch├¡nh l├á key ─æß╗â VR fetch metadata */
  lessonDocId: string;
  /** T├¬n file .unity (VD: "Bathroom", "Farm") */
  sceneName: string;
  /** T├¬n b├ái hß╗ìc hiß╗ân thß╗ï */
  lessonName: string;
  /** M├ú PIN ─æang kß║┐t nß╗æi vß╗¢i K├¡nh VR */
  pin: string;
  /** ID hß╗ô s╞í trß║╗ ─æang ─æ╞░ß╗úc chß╗ìn */
  childId: string;
}

export default function StartLessonButton({
  lessonDocId,
  sceneName,
  lessonName,
  pin,
  childId,
}: StartLessonButtonProps) {
  const [status, setStatus] = useState<"idle" | "sending" | "success" | "error">("idle");
  const [errorMsg, setErrorMsg] = useState("");
  const router = useRouter();
  const { user } = useAuth();

  // Γ£à ─Éß╗ìc URL live ΓÇö ─æß║úm bß║úo lß║Ñy trß║íng th├íi thß╗▒c tß║┐ ngay tß║íi thß╗¥i ─æiß╗âm bß║Ñm
  // Khi VRConnectionMonitor xo├í ?pin&vr khß╗Åi URL, hook n├áy sß║╜ re-render tß╗⌐c th├¼
  const searchParams = useSearchParams();
  const livePin = searchParams.get("pin") || pin;
  const isVRConnected = searchParams.get("vr") === "connected";

  const handleStart = async () => {
    // Guard 1: Kh├┤ng c├│ PIN ΓåÆ ch╞░a gh├⌐p nß╗æi
    if (!livePin) {
      setStatus("error");
      setErrorMsg("Ch╞░a kß║┐t nß╗æi K├¡nh VR. Vui l├▓ng gh├⌐p nß╗æi tr╞░ß╗¢c.");
      return;
    }

    // Guard 2: PIN c├│ nh╞░ng trß║íng th├íi VR kh├┤ng c├▓n "connected" trong URL
    // ΓåÆ ─É├óy l├á tr╞░ß╗¥ng hß╗úp k├¡nh VR ─æ├ú tß║»t app ngay sau khi render trang
    if (!isVRConnected) {
      setStatus("error");
      setErrorMsg("K├¡nh VR ─æ├ú mß║Ñt kß║┐t nß╗æi. Vui l├▓ng kiß╗âm tra thiß║┐t bß╗ï v├á gh├⌐p nß╗æi lß║íi.");
      return;
    }

    setStatus("sending");
    setErrorMsg("");

    try {
      // Gß╗¡i lß╗çnh khß╗ƒi chß║íy l├¬n RTDB ΓåÆ K├¡nh VR sß║╜ nhß║¡n v├á chuyß╗ân Scene
      const sessionId = await startLessonOnDevice(livePin, sceneName, lessonDocId, user?.uid || "");

      setStatus("success");

      // Chuyß╗ân h╞░ß╗¢ng sang trang Session sau 1.2 gi├óy (─æß╗â user nh├¼n thß║Ñy tick xanh)
      setTimeout(() => {
        const q = new URLSearchParams();
        q.set("childId", childId);
        q.set("pin", livePin);
        q.set("vr", "connected"); // ΓÜá∩╕Å QUAN TRß╗îNG: Phß║úi c├│ vr=connected ─æß╗â dashboard kh├┤ng t╞░ß╗ƒng l├á mß║Ñt pin
        q.set("session", sessionId);
        q.set("lesson", lessonDocId);
        router.push(`/dashboard/expert/session/${sessionId}?${q.toString()}`);
      }, 1200);
    } catch (error: any) {
      console.error("StartLesson Error:", error);
      setStatus("error");
      setErrorMsg(error.message || "Kh├┤ng thß╗â gß╗¡i lß╗çnh tß╗¢i K├¡nh VR.");
    }
  };

  // Nß║┐u ch╞░a c├│ PIN hoß║╖c VR ─æ├ú ngß║»t kß║┐t nß╗æi ΓåÆ Hiß╗çn n├║t x├ím disabled
  if (!livePin || !isVRConnected) {
    return (
      <button
        disabled
        className="w-full mt-2 py-4 bg-zinc-200 dark:bg-zinc-800 text-zinc-400 dark:text-zinc-600 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 cursor-not-allowed border border-zinc-300 dark:border-zinc-700"
      >
        <AlertCircle size={16} />
        {!livePin ? "Ch╞░a kß║┐t nß╗æi VR" : "VR mß║Ñt kß║┐t nß╗æi"}
      </button>
    );
  }

  return (
    <>
      <button
        onClick={handleStart}
        disabled={status === "sending" || status === "success"}
        className={`w-full mt-2 py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 transition-all active:scale-95 ${
          status === "success"
            ? "bg-emerald-600 text-white shadow-xl shadow-emerald-500/20"
            : status === "sending"
            ? "bg-blue-500 text-white/80 cursor-wait"
            : "bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 hover:bg-blue-600 hover:text-white dark:hover:bg-blue-600 shadow-xl shadow-zinc-200/50 dark:shadow-none"
        }`}
      >
        {status === "sending" && (
          <>
            <Loader2 size={18} className="animate-spin" />
            ─Éang gß╗¡i lß╗çnh...
          </>
        )}
        {status === "success" && (
          <>
            <CheckCircle2 size={18} />
            ─É├ú gß╗¡i ΓÇö ─Éang chuyß╗ân h╞░ß╗¢ng...
          </>
        )}
        {status === "idle" && (
          <>
            <PlayCircle size={18} />
            Khß╗ƒi chß║íy tr├¬n K├¡nh VR
          </>
        )}
        {status === "error" && (
          <>
            <PlayCircle size={18} />
            Thß╗¡ lß║íi
          </>
        )}
      </button>

      {/* Error message */}
      {status === "error" && errorMsg && (
        <div className="mt-2 flex items-center gap-2 px-4 py-2 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-xl animate-in fade-in slide-in-from-top-2">
          <AlertCircle size={14} className="text-red-500 shrink-0" />
          <p className="text-[11px] font-semibold text-red-600 dark:text-red-400">{errorMsg}</p>
        </div>
      )}
    </>
  );
}

