import React from "react";
import { redirect } from "next/navigation";
import { cookies } from "next/headers";
import { getLessons } from "@/actions/lessons";
import { getSchedules } from "@/actions/schedule";
import { getCachedAIRecommendations } from "@/actions/ai-recommendations";
import ScheduleClient from "./ScheduleClient";

interface PageProps {
  searchParams: Promise<{ childId?: string }>;
}

export default async function ScheduleServerPage({ searchParams }: PageProps) {
  const params = await searchParams;
  const childId = params.childId;

  // 1. Kiß╗âm tra childId
  if (!childId) {
    // Nß║┐u kh├┤ng c├│ childId, quay vß╗ü trang dashboard ch├¡nh ─æß╗â chß╗ìn b├⌐
    redirect("/dashboard/expert");
  }

  // 2. Lß║Ñy expertUid tß╗½ cookie/auth
  const cookieStore = await cookies();
  const sessionCookie = cookieStore.get("session")?.value;
  // Giß║ú lß║¡p lß║Ñy expertUid tß╗½ cookie (thß╗▒c tß║┐ dß╗▒ ├ín ─æang d├╣ng action check auth nh╞░ng ─æ├óy l├á fallback)
  // Thß╗▒c tß║┐ `getSchedules` y├¬u cß║ºu expertUid nß║┐u muß╗æn bß║úo mß║¡t, nh╞░ng schema hiß╗çn tß║íi chß╗ë lß╗ìc theo childId
  const expertUid = "expert123"; // TODO: N├¬n lß║Ñy tß╗½ AuthContext hoß║╖c getExpertProfile() nß║┐u cß║ºn

  // 3. Fetch dß╗» liß╗çu song song
  const [lessonsRes, schedulesRes, aiRes] = await Promise.all([
    getLessons(),
    getSchedules(childId),
    getCachedAIRecommendations(childId)
  ]);

  const lessons = lessonsRes.success ? lessonsRes.lessons || [] : [];
  const schedules = schedulesRes.success ? schedulesRes.schedules || [] : [];
  
  // Tr├¡ch xuß║Ñt danh s├ích ID b├ái hß╗ìc gß╗úi ├╜ tß╗½ AI
  let suggestedLessonIds: string[] = [];
  if (aiRes.success && aiRes.recommendations) {
    suggestedLessonIds = aiRes.recommendations.map(r => r.lessonId);
  }

  return (
    <ScheduleClient 
      childId={childId}
      expertUid={expertUid}
      initialSchedules={schedules}
      lessons={lessons}
      suggestedLessonIds={suggestedLessonIds}
    />
  );
}

