} from "lucide-react";

interface ControlSidebarProps {
  sessionTime: number;
  telemetry: any;
  onPauseLesson?: () => void;
  onForceSkip?: () => void;
  onResumeLesson?: () => void;
  onSendNpcScript?: (text: string) => Promise<void>;
}

export default function ControlSidebar({ 
  sessionTime, 
  telemetry,
  onPauseLesson,
  onForceSkip,
  onResumeLesson,
  onSendNpcScript
}: ControlSidebarProps) {
  const formatTime = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
