                 <div className="h-full bg-blue-600 w-[45%]" />
              </div>
           </div>

           <div className="space-y-2">
              <QuestStep label="Wet Hands" isCompleted={true} />
              <QuestStep label="Apply Soap" isActive={true} />
              <QuestStep label="Scrub & Rinse" />
           </div>
        </div>

        {/* Remote Commands */}
        <div className="space-y-4">
           <h4 className="text-[10px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-2 border-b border-zinc-100 dark:border-zinc-800 pb-2">
              <Zap size={12} /> REMOTE COMMANDS (RTDB)
           </h4>

           <div className="grid grid-cols-2 gap-3">
              <CommandButton 
                icon={isPaused ? Play : Pause} 
                label={isPaused ? "RESUME" : "PAUSE"} 
                onClick={handlePauseToggle} 
              />
              <CommandButton icon={RotateCcw} label="RESET STAGE" />
              <CommandButton 
                icon={ArrowRight} 
                label="NEXT STEP" 
                color="blue" 
                onClick={onForceSkip}
              />
              <CommandButton icon={Target} label="CALIBRATE" />
            </div>

            {/* NPC TTS Input */}
            <div className="mt-4 p-4 bg-zinc-50 dark:bg-zinc-800/50 rounded-2xl border border-zinc-100 dark:border-zinc-800 space-y-3">
              <div className="flex items-center gap-2 text-zinc-900 dark:text-white">
                 <MessageCircle size={14} className="text-blue-500" />
                 <span className="text-[10px] font-black uppercase tracking-wider">N├│i qua NPC (TTS)</span>
              </div>
              <textarea
                value={npcText}
                onChange={(e) => setNpcText(e.target.value)}
                placeholder="Nhß║¡p nß╗Öi dung thoß║íi tiß║┐ng Viß╗çt (tß╗æi ─æa 200 k├╜ tß╗▒)..."
                maxLength={200}
                className="w-full bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl p-3 text-xs text-zinc-900 dark:text-white resize-none h-20 focus:outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500"
