"use client";

import { useEffect, useState, useCallback } from "react";
import { useRoomContext } from "@livekit/components-react";
import { RoomEvent } from "livekit-client";

export interface QuestStatusPayload {
  quest_name: string;
  status: "active" | "matched" | string;
  phrases_cached?: boolean;
}

export function useLiveKitDataChannel(
  onQuestStatus?: (status: QuestStatusPayload) => void
) {
  let room: any = null;
  try {
    room = useRoomContext();
  } catch (e) {
    // If used outside LiveKitRoom context, gracefully handle null
  }

  const [lastEvent, setLastEvent] = useState<any>(null);

  const sendDataPacket = useCallback(
    async (eventName: string, extraData?: Record<string, any>) => {
      if (!room || !room.localParticipant) {
        console.warn("[LiveKitDataChannel] Room or local participant not available");
        return false;
      }

      try {
        const payload = JSON.stringify({
          event: eventName,
          ...(extraData || {}),
        });
        const encoder = new TextEncoder();
        const data = encoder.encode(payload);

        await room.localParticipant.publishData(data, { reliable: true });
        console.log(`[LiveKitDataChannel] Sent ${eventName}:`, payload);
        return true;
      } catch (err) {
        console.error(`[LiveKitDataChannel] Failed to send ${eventName}:`, err);
        return false;
      }
    },
    [room]
  );

  const sendVerbalHint = useCallback(async () => {
    return sendDataPacket("VERBAL_HINT");
  }, [sendDataPacket]);

  const sendSpeakScript = useCallback(
    async (text: string) => {
      return sendDataPacket("SPEAK_SCRIPT", { text });
    },
    [sendDataPacket]
  );

  useEffect(() => {
    if (!room) return;

    const handleData = (
      payload: Uint8Array,
      participant: any,
      kind: any,
      topic?: string
    ) => {
      try {
        const decoder = new TextDecoder();
        const text = decoder.decode(payload);
        const data = JSON.parse(text);
        setLastEvent(data);

        if (data.event === "QUEST_STATUS" && onQuestStatus) {
          onQuestStatus({
            quest_name: data.quest_name,
            status: data.status,
            phrases_cached: data.phrases_cached,
          });
        }
      } catch (err) {
        console.error("[LiveKitDataChannel] Error parsing incoming packet:", err);
      }
    };

    room.on(RoomEvent.DataReceived, handleData);
    return () => {
      room.off(RoomEvent.DataReceived, handleData);
    };
  }, [room, onQuestStatus]);

  return {
    sendDataPacket,
    sendVerbalHint,
    sendSpeakScript,
    lastEvent,
    isReady: Boolean(room && room.state === "connected"),
  };
}

"use client";

import { rtdb } from "@/lib/firebase/client";
import { ref, get, update, remove, onValue, onChildAdded, push, set, serverTimestamp } from "firebase/database";

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Tß║Ñt cß║ú logic RTDB pairing nß║▒m ß╗ƒ ─æ├óy, c├íc component chß╗ë gß╗ìi h├ám
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Kß║┐t nß╗æi (Pair) vß╗¢i thiß║┐t bß╗ï VR bß║▒ng m├ú PIN.
 * Ghi child_id hiß╗çn tß║íi v├áo RTDB ngay lß║¡p tß╗⌐c.
 * Trß║ú vß╗ü pin.
 */
export async function pairWithDevice(pinCode: string, childId: string, hostId: string): Promise<{ pin: string }> {
  const pinRef = ref(rtdb, `pairing_codes/${pinCode}`);
  const snapshot = await get(pinRef);

  if (!snapshot.exists()) {
    throw new Error("M├ú PIN kh├┤ng tß╗ôn tß║íi hoß║╖c ─æ├ú hß║┐t hß║ín.");
  }

  const data = snapshot.val();
  if (data.status !== "waiting") {
    throw new Error("Thiß║┐t bß╗ï kh├┤ng ß╗ƒ trß║íng th├íi chß╗¥ gh├⌐p nß╗æi.");
  }

  // Kh├┤ng tß║ío sessionId l├║c Pair, chß╗ë cß║¡p nhß║¡t trß║íng th├íi
  await update(pinRef, {
    status: "paired",
    current_child_id: childId || "",
    host_id: hostId,
  });

  return { pin: pinCode };
}

/**
 * Gß╗¡i lß╗çnh chß║íy B├ái hß╗ìc tß╗¢i K├¡nh VR.
 * L├║c n├áy mß╗¢i sinh SessionId v├á truyß╗ün k├¿m theo LessonId + SceneName.
 * @param sceneName - T├¬n ch├¡nh x├íc cß╗ºa file .unity (VD: "Bathroom", "Farm")
 * @param lessonId  - ID b├ái hß╗ìc tr├¬n Firestore (VD: "WashingHand_1")
 * @param hostId    - UID cß╗ºa Expert ─æang ─æiß╗üu khiß╗ân buß╗òi hß╗ìc
 */
export async function startLessonOnDevice(pinCode: string, sceneName: string, lessonId: string, hostId: string): Promise<string> {
  const pinRef = ref(rtdb, `pairing_codes/${pinCode}`);
  const sessionId = crypto.randomUUID();

  let livekitToken = "";
  try {
    const tokenRes = await fetch(`/api/livekit-token?room=${sessionId}&username=vr_${pinCode}`);
    if (tokenRes.ok) {
      const tokenData = await tokenRes.json();
      livekitToken = tokenData.token;
    }
  } catch (e) {
    console.warn("[RTDB] Could not generate VR LiveKit token:", e);
  }

  await update(pinRef, {
    current_lesson_id: lessonId,
    current_session_id: sessionId,
    target_scene_name: sceneName,
    host_id: hostId,
    livekit_token: livekitToken,
  });

  return sessionId;
}

/**
 * Cß║¡p nhß║¡t child_id tr├¬n RTDB khi Expert ─æß╗òi hß╗ô s╞í trß║╗.
 * Gß╗ìi h├ám n├áy mß╗ùi khi user chß╗ìn profile mß╗¢i.
 */
export async function updateChildOnDevice(pinCode: string, childId: string): Promise<void> {
  const pinRef = ref(rtdb, `pairing_codes/${pinCode}`);
  await update(pinRef, {
    current_child_id: childId || "",
  });
}

/**
 * Ngß║»t kß║┐t nß╗æi: set status vß╗ü "waiting" v├á xo├í c├íc field session.
 */
export async function disconnectDevice(pinCode: string): Promise<void> {
  const pinRef = ref(rtdb, `pairing_codes/${pinCode}`);
  await update(pinRef, {
    status: "waiting",
    current_child_id: "",
    current_lesson_id: "",
    current_session_id: "",
    target_scene_name: "",
  });
}

/**
 * Kß║┐t th├║c b├ái hß╗ìc tr├¬n K├¡nh VR.
 * Xo├í session hiß╗çn tß║íi ─æß╗â K├¡nh VR tß╗▒ ─æß╗Öng quay vß╗ü Lobby.
 */
export async function endLessonOnDevice(pinCode: string): Promise<void> {
  const pinRef = ref(rtdb, `pairing_codes/${pinCode}`);
  await update(pinRef, {
    current_lesson_id: "",
    current_session_id: "",
    target_scene_name: "",
  });
}

/**
 * Giao tiß║┐p Handshake: Lß║»ng nghe VR x├íc nhß║¡n ─æ├ú v├áo scene b├ái hß╗ìc.
 *
 * VR sß║╜ tß╗▒ tß║ío node `LIVE_SESSIONS/{sessionId}` v├á ghi `vr_state` sau khi scene load xong.
 * H├ám n├áy lß║»ng nghe node ─æ├│ v├á gß╗ìi callback khi `vr_state.status === "ready"`.
 *
 * @param sessionId    - Session ID ─æ├ú ─æ╞░ß╗úc giao cho VR qua pairing_codes
 * @param onReady      - Callback khi VR x├íc nhß║¡n v├áo scene
 * @param onEnded      - Callback khi VR kß║┐t th├║c b├ái hß╗ìc (status = "ended")
 * @param onDisconnect - Callback khi VR ngß║»t ─æß╗Öt ngß╗Öt (status = "disconnected")
 * @returns Unsubscribe function ΓÇö gß╗ìi khi component unmount
 */
export function subscribeToVrHandshake(
  sessionId: string,
  onReady: (data: { scene_name: string; confirmed_at: number }) => void,
  onEnded?: () => void,
  onDisconnect?: () => void,
): () => void {
  const vrStateRef = ref(rtdb, `live_sessions/${sessionId}/vr_state`);

  const unsubscribe = onValue(vrStateRef, (snapshot) => {
    if (!snapshot.exists()) return;
    const data = snapshot.val();

    if (data?.status === "ready") {
      onReady({
        scene_name: data.scene_name || "",
        confirmed_at: data.confirmed_at || Date.now(),
      });
    } else if (data?.status === "ended") {
      onEnded?.();
    } else if (data?.status === "disconnected") {
      onDisconnect?.();
    }
  });

  // Trß║ú vß╗ü h├ám dß╗ìn dß║╣p listener khi component unmount
  return unsubscribe;
}

/**
 * Lß║»ng nghe luß╗ông dß╗» liß╗çu Telemetry tß╗½ VR.
 * VR ─æß║⌐y dß╗» liß╗çu v├áo behavior_snapshots/sessionId/timestamp
 */
export function subscribeToTelemetry(
  sessionId: string,
  onNewSnapshot: (timestamp: string, snapshot: any) => void
): () => void {
  const telemetryRef = ref(rtdb, `behavior_snapshots/${sessionId}`);
  
  const unsubscribe = onChildAdded(telemetryRef, (snapshot) => {
    if (snapshot.exists()) {
      onNewSnapshot(snapshot.key as string, snapshot.val());
    }
  });

  return unsubscribe;
}


/**
 * Lß║»ng nghe WebRTC Offer tß╗½ thiß║┐t bß╗ï VR
 */
export function subscribeToWebRTCOffer(
  sessionId: string,
  onOffer: (offer: string) => void
): () => void {
  const offerRef = ref(rtdb, `webrtc_signaling/${sessionId}/offer`);
  const unsubscribe = onValue(offerRef, (snapshot) => {
    if (snapshot.exists()) {
      onOffer(snapshot.val());
    }
  });
  return unsubscribe;
}

